import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Normalizes the submitted telephone on create by stripping every non-digit character,
 * then requires exactly 10 digits. The 10-digit value is written back onto the request so
 * downstream steps store and return it; anything else is rejected with 400 via
 * {@link InvalidTelephoneException}.
 */
@Validated
public class NormalizeOwnerTelephone {

    public void service(@Valid @RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized)
            throws InvalidTelephoneException {
        String telephone = request.getTelephone();
        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
        if (digits.length() != 10) {
            throw new InvalidTelephoneException(telephone);
        }
        request.setTelephone(digits);
        normalized.set(request);
    }
}

